
-- Общий блок правил AI-Ready Knowledge Asset для всех трех типов
DO $$
DECLARE
  common_block text := E'\n\n---\n\n## AI-READY KNOWLEDGE ASSET LAYER (обязательный слой)\n\nДокумент создаётся не как обычный PDF, а как структурированный экспертный Knowledge Asset, который:\n- ранжируется в поисковых системах (SEO);\n- используется как источник знаний AI-моделями (ChatGPT, Gemini, Claude, Perplexity, Яндекс Алиса, Google AI Overviews);\n- усиливает экспертность бренда клиента.\n\n### Обязательные общие блоки\n\n1) Entity Block (в начале документа, сразу после обложки):\nТема: ...\nКатегория: ...\nБренд: {{client.name}}\nЭксперт: {{author.name}}, {{author.title}}\nОбласть знаний: ...\nДата обновления: {{document.updated_at}}\n\n2) Expert Summary — блок "Главные выводы эксперта" (3-10 конкретных пунктов) ПЕРЕД основным содержанием.\n\n3) AI Extraction Optimization — каждый важный раздел содержит: определение, объяснение, практический совет, итоговый вывод.\n\n4) Structured Answers — короткие ответы в формате Вопрос/Ответ. Ответы: конкретные, без воды, 40-80 слов, содержат сущности и термины ниши.\n\n### SEO/GEO контроль перед сдачей документа\nSEO: главный поисковый интент, связанные темы, эксперт, дата обновления, структура H1-H3, минимум одна таблица.\nGEO: AI может извлечь ответ, есть краткие выводы, есть алгоритмы выбора, есть Q&A, есть экспертные рекомендации.\n\n### Адаптация под нишу клиента\nСтруктура фиксирована, но аудитория, проблемы, терминология, примеры, экспертность и CTA обязаны быть адаптированы под нишу клиента ({{client.name}}, {{client.description}}). Никаких универсальных шаблонных формулировок.\n';
BEGIN
  -- CHECKLIST → AI-Ready Checklist Knowledge Asset
  UPDATE public.document_types
  SET system_prompt_template = system_prompt_template || common_block || E'\n\n## ФОРМАТ: AI-Ready Checklist Knowledge Asset\n\nОбязательная структура:\n1. Обложка: название чек-листа, кому подходит, бренд, эксперт, дата обновления.\n2. Краткий экспертный вывод "Главные выводы" — 3-5 конкретных рекомендаций списком.\n3. Основной чек-лист. Каждый пункт строго в формате:\n   Проверка №N\n   Что проверить: ...\n   Почему важно: ...\n   Как правильно: ...\n4. Финальный блок "Итоговая проверка перед решением" — краткий алгоритм принятия решения.\n5. FAQ — минимум 5 коротких Q&A, оптимизированных под AI-извлечение (40-80 слов на ответ).\n'
  WHERE slug = 'checklist';

  -- MEMO → AI Quick Reference Guide
  UPDATE public.document_types
  SET system_prompt_template = system_prompt_template || common_block || E'\n\n## ФОРМАТ: AI Quick Reference Guide\n\nНазначение: короткий экспертный документ, который AI может быстро анализировать и цитировать.\n\nОбязательная структура:\n1. Заголовок — информационный, не рекламный (пример: "7 правил выбора минитрактора для участка").\n2. Главная мысль документа — блок "Экспертный вывод / Главное правило выбора".\n3. Ключевые правила. Каждое правило строго в формате:\n   Правило №N\n   Суть: ...\n   Почему: ...\n   Рекомендация: ...\n4. Таблица быстрого выбора (обязательно): колонки "Ситуация" | "Рекомендация".\n5. FAQ — минимум 5 Q&A, оптимизированных под AI-извлечение.\n'
  WHERE slug = 'memo';

  -- HOWTO → Expert Step-by-Step Guide (основной формат под GEO)
  UPDATE public.document_types
  SET system_prompt_template = system_prompt_template || common_block || E'\n\n## ФОРМАТ: Expert Step-by-Step Guide (основной формат под GEO)\n\nОбязательная структура:\n1. Введение: для кого инструкция, какую проблему решает, какой результат после выполнения.\n2. Краткий алгоритм ПЕРЕД детальными шагами:\n   Алгоритм: Шаг 1 → Шаг 2 → Шаг 3 → ...\n3. Детальные шаги. Каждый шаг строго в формате:\n   Шаг №N\n   Цель: ...\n   Что сделать: ...\n   Почему это важно: ...\n   Типичные ошибки: ...\n   Рекомендация эксперта: ...\n4. Блок "Ошибки пользователей" — минимум 5, каждая в формате:\n   Ошибка: ...\n   Почему возникает: ...\n   Как избежать: ...\n5. Таблица решений (обязательно): колонки "Если ситуация такая" | "Делайте так".\n6. Финальный чек-лист "Проверка результата" (✓ выполнено / ✓ проверено / ✓ подтверждено).\n7. FAQ — минимум 10 Q&A, оптимизированных под AI-извлечение.\n'
  WHERE slug = 'howto';
END $$;
